import React, { useState, useEffect, useCallback, useMemo } from "react";
import {
  Box,
  Typography,
  TextField,
  Button,
  CircularProgress,
  Checkbox,
  Tooltip,
  Avatar,
  useTheme,
} from "@mui/material";
import AvatarView from "../../../components/AvatarView";
import {
  ArrowBack as ArrowBackIcon,
} from "@mui/icons-material";
import { useNavigate } from "react-router-dom";
import { useSelector } from "react-redux";
import { toast } from "react-hot-toast";
import DataTable from "../../../components/DataTable";

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const SendNotification = () => {
  const navigate = useNavigate();
  const theme = useTheme();
  const token = useSelector((state) => state.auth.token);

  // Form State - Section 1
  const [title, setTitle] = useState("");
  const [message, setMessage] = useState("");

  // Users Table State - Section 2
  const [users, setUsers] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [orderBy, setOrderBy] = useState("created_at");
  const [order, setOrder] = useState("desc");
  const [searchTerm, setSearchTerm] = useState("");

  // Selection State
  const [selectedUserIds, setSelectedUserIds] = useState([]);
  const [sendToAll, setSendToAll] = useState(true);

  // Sending State
  const [isSending, setIsSending] = useState(false);

  const isSubmitDisabled = useMemo(() => {
    const hasRequiredFields = title.trim().length > 0 && message.trim().length > 0;
    const hasRecipients = sendToAll || selectedUserIds.length > 0;
    return !hasRequiredFields || !hasRecipients;
  }, [title, message, sendToAll, selectedUserIds]);

  // ── Fetch Users ─────────────────────────────────────────────────────────
  const fetchUsers = useCallback(
    async (apiPage, limit) => {
      if (!token) return;
      setIsLoading(true);
      try {
        const queryParams = new URLSearchParams({
          page: apiPage,
          limit: limit,
          sort_by: orderBy,
          sort_order: order,
          q: searchTerm,
        });

        const res = await fetch(
          `${BASE_URL}/users/with-profile?${queryParams.toString()}`,
          {
            method: "GET",
            headers: {
              Authorization: `Bearer ${token}`,
              "Content-Type": "application/json",
            },
          }
        );

        const json = await res.json();
        if (!res.ok || json.error) {
          throw new Error(json.message || "Failed to fetch users");
        }

        setUsers(json.data.users || []);
        setTotalCount(json.data.pagination?.total || 0);
      } catch (err) {
        console.error("Error fetching users:", err);
        toast.error(err.message || "Failed to fetch users");
      } finally {
        setIsLoading(false);
      }
    },
    [token, orderBy, order, searchTerm]
  );

  useEffect(() => {
    if (token) {
      fetchUsers(page + 1, rowsPerPage);
    }
  }, [page, rowsPerPage, fetchUsers, token]);

  const handleSortChange = (property) => {
    const isAsc = orderBy === property && order === "asc";
    setOrder(isAsc ? "desc" : "asc");
    setOrderBy(property);
    setPage(0);
  };

  // ── User Selection ──────────────────────────────────────────────────────
  const toggleUser = (userId) => {
    setSelectedUserIds((prev) =>
      prev.includes(userId)
        ? prev.filter((id) => id !== userId)
        : [...prev, userId]
    );
  };

  const toggleSelectAll = () => {
    if (selectedUserIds.length === users.length) {
      setSelectedUserIds([]);
    } else {
      setSelectedUserIds(users.map((u) => u.id));
    }
  };

  const toggleSendToAll = () => {
    setSendToAll((prev) => {
      if (!prev) {
        setSelectedUserIds([]);
      }
      return !prev;
    });
  };

  // ── Send Notification ──────────────────────────────────────────────────
  const handleSendSubmit = async () => {
    if (!title.trim() || !message.trim()) {
      toast.error("Title and Message are required");
      return;
    }
    if (!sendToAll && selectedUserIds.length === 0) {
      toast.error("Please select at least one recipient");
      return;
    }

    setIsSending(true);
    const toastId = toast.loading("Sending notification...");
    try {
      let url;
      let payload = {
        title: title,
        body: message,
        type: "custom",
        metadata: {},
        send_push: true,
      };

      if (sendToAll) {
        url = `${BASE_URL}/notifications/broadcast-active`;
      } else {
        url = `${BASE_URL}/notifications/broadcast-selected`;
        payload = { ...payload, user_ids: selectedUserIds };
      }

      const res = await fetch(url, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || "Failed to send notification");
      }

      toast.success("Notification sent successfully!", { id: toastId });
      setTimeout(() => navigate("/broadcast-notifications"), 1000);
    } catch (err) {
      console.error(err);
      toast.error(err.message || "Failed to send notification", {
        id: toastId,
      });
    } finally {
      setIsSending(false);
    }
  };

  // ── Table Columns ────────────────────────────────────────────────────────
  const columns = [
    {
      id: "checkbox",
      label: (
        <Checkbox
          checked={selectedUserIds.length === users.length && users.length > 0}
          indeterminate={selectedUserIds.length > 0 && selectedUserIds.length < users.length}
          onChange={toggleSelectAll}
          sx={{
            p: 0,
            color: "#8B8D97",
            "&.Mui-checked": { color: "#4CC66E" },
          }}
        />
      ),
      render: (row) => (
        <Checkbox
          checked={selectedUserIds.includes(row.id)}
          onChange={() => toggleUser(row.id)}
          onClick={(e) => e.stopPropagation()}
          sx={{
            p: 0,
            color: "#8B8D97",
            "&.Mui-checked": { color: "#4CC66E" },
          }}
        />
      ),
    },
    {
      id: "name",
      label: "Name",
      sortable: true,
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
          <AvatarView
            user={row}
            alt={row.name}
            previewTitle={row.name}
            sx={{
              width: 32,
              height: 32,
              bgcolor: "#4CC66E",
              color: "#000",
              fontSize: "0.75rem",
              fontWeight: 700,
              fontFamily: "'Montserrat', sans-serif",
              flexShrink: 0,
            }}
          />
          <Box>
            <Typography
              sx={{
                color: "#FFFFFF",
                fontSize: "0.8rem",
                fontFamily: "'Montserrat', sans-serif",
                fontWeight: 500,
                lineHeight: 1.2,
              }}
            >
              {row.name}
            </Typography>
            <Typography sx={{ color: "#8B8D97", fontSize: "0.7rem", fontFamily: "'Montserrat', sans-serif" }}>
              {row.email}
            </Typography>
          </Box>
        </Box>
      ),
    },
    {
      id: "created_at",
      label: "Joined",
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: "#8B8D97", fontSize: "0.8rem", fontFamily: "'Montserrat', sans-serif" }}>
          {row.created_at
            ? new Date(row.created_at).toLocaleDateString("en-GB", {
                day: "2-digit",
                month: "short",
                year: "numeric",
              })
            : "-"}
        </Typography>
      ),
    },
  ];

  return (
    <Box sx={{ p: { xs: 1.5, sm: 2, md: 3 } }}>
      {/* Header */}
      <Box sx={{ display: "flex", flexDirection: { xs: "column", sm: "row" }, alignItems: { xs: "flex-start", sm: "center" }, gap: { xs: 1.5, sm: 2 }, mb: { xs: 2, md: 3 } }}>
        <Tooltip title="Back to Notifications">
          <Button
            onClick={() => navigate("/broadcast-notifications")}
            variant="outlined"
            sx={{
              minWidth: 40,
              width: 40,
              height: 40,
              p: 0,
              borderRadius: "12px",
              color: theme.palette.primary.main,
              borderColor: "rgba(255,255,255,0.12)",
              bgcolor: theme.palette.background.paper,
              '&:hover': { bgcolor: 'rgba(255,255,255,0.04)' },
            }}
          >
            <ArrowBackIcon sx={{ fontSize: 20 }} />
          </Button>
        </Tooltip>
        <Box>
          <Typography
            variant="h5"
            sx={{ 
              color: theme.palette.text.primary,
              fontWeight: 700,
              fontFamily: theme.typography.fontFamily,
              fontSize: { xs: "1.3rem", md: "1.8rem" },
            }}
          >
            Send Notification
          </Typography>
          <Typography sx={{ color: theme.palette.text.secondary, mt: 0.5, fontSize: "0.95rem" }}>
            Compose your broadcast and choose whether to send it to all users or specific recipients.
          </Typography>
        </Box>

       
      </Box>

      {/* Main Container */}
      <Box sx={{ display: "flex", flexDirection: "column", gap: { xs: 2, md: 3 } }}>
        {/* ── SECTION 1: Notification Form ─────────────────────────────────────── */}
        <Box
          sx={{
            bgcolor:'#001e08ff',
            border: "1px solid rgba(255, 255, 255, 0.08)",
            borderRadius: "20px",
            p: { xs: 2, md: 3 },
            display: "flex",
            flexDirection: "column",
            gap: 3,
            width: "100%",
            boxShadow: "0 24px 60px rgba(0,0,0,0.35)",
          }}
        >
          <Typography sx={{ color: "#FFFFFF", fontWeight: 600, fontSize: { xs: "0.95rem", md: "1rem" } }}>
            Notification Details
          </Typography>

          {/* Title Field */}
          <Box>
            <Typography sx={{ color: "#B0B3B8", fontSize: { xs: "0.8rem", md: "0.875rem" }, mb: 1 }}>
              Title
            </Typography>
            <TextField
              fullWidth
              placeholder="E.g. System Maintenance"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              autoComplete="off"
          />
          </Box>

          <Box>
            <Box>
              <Typography sx={{ color: theme.palette.text.secondary, fontSize: { xs: "0.8rem", md: "0.875rem" }, mb: 1 }}>
                Message
              </Typography>
              <TextField
                multiline
                fullWidth
                rows={3}
                placeholder="Type your message here..."
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                // sx={{
                //   bgcolor: theme.palette.background.default,
                //   borderRadius: "12px",
                //   fontFamily: theme.typography.fontFamily,
                //   fontSize: { xs: "0.875rem", md: "0.95rem" },
                // }}
              />
            </Box>
          </Box>

        <Box sx={{display:'flex',alignItems:'center',justifyContent:'space-between'}}>
              {/* Send to All Toggle */}
          <Box
            onClick={toggleSendToAll}
            sx={{
              display: "flex",
              flexDirection: { xs: "column", sm: "row" },
              alignItems: { xs: "flex-start", sm: "center" },
              justifyContent: "space-between",
              gap: 2,
              p: 2,
              bgcolor: theme.palette.background.default,
              border: "1px solid rgba(255,255,255,0.08)",
              borderRadius: "16px",
              cursor: "pointer",
              transition: "all 0.2s",
              "&:hover": { bgcolor: "rgba(255,255,255,0.04)" },
            }}
          >
            <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
              <Checkbox
                checked={sendToAll}
                onChange={toggleSendToAll}
                onClick={(e) => e.stopPropagation()}
                sx={{
                  p: 0,
                  color: theme.palette.text.secondary,
                  "&.Mui-checked": { color: theme.palette.primary.main },
                }}
              />
              <Box>
                <Typography sx={{ color: theme.palette.text.primary, fontWeight: 700, fontSize: "0.95rem" }}>
                  Send to All Active Users
                </Typography>
                <Typography sx={{ color: theme.palette.text.secondary, fontSize: "0.8rem" }}>
                  {sendToAll ? "Notification will go to every active user." : "Select recipients from the table below."}
                </Typography>
              </Box>
            </Box>
          </Box>


          {/* Send Button */}
          <Button
            onClick={handleSendSubmit}
            disabled={isSending || isSubmitDisabled}
            
            variant="contained"
            sx={{
              bgcolor: '#9F6EDA',
              color: theme.palette.primary.contrastText,
              fontWeight: 700,
            
              "&:hover": { bgcolor:' #9F6EDA'},
             
            }}
          >
            {isSending ? (
              <CircularProgress size={24} color="inherit" />
            ) : (
              "Send Notification"
            )}
          </Button>
        </Box>

        </Box>

        {/* ── SECTION 2: Users Table ─────────────────────────────────────────── */}
        {!sendToAll && (
          <Box sx={{ width: "100%" }}>
            <DataTable
              title={`Select Recipients (${selectedUserIds.length})`}
              columns={columns}
              data={users}
              isLoading={isLoading}
              searchTerm={searchTerm}
              onSearchChange={(val) => {
                setSearchTerm(val);
                setPage(0);
              }}
              orderBy={orderBy}
              order={order}
              onSortChange={handleSortChange}
              pagination={{
                page: page,
                rowsPerPage: rowsPerPage,
                totalCount: totalCount,
                onPageChange: (_, newPage) => setPage(newPage),
                onRowsPerPageChange: (e) => {
                  setRowsPerPage(parseInt(e.target.value, 10));
                  setPage(0);
                },
              }}
              emptyTitle="No users found"
              emptyMessage="No users available to send notification to."
            />
          </Box>
        )}
      </Box>
    </Box>
  );
};

export default SendNotification;
